from collections import Counter


def transform(grid):
    # Each 3x3 tile in the 30x30 noisy canvas becomes one output cell.
    # The non-background marker color identifies that tile.
    out = []
    for tile_r in range(10):
        row = []
        for tile_c in range(10):
            counts = Counter(
                grid[r][c]
                for r in range(tile_r * 3, tile_r * 3 + 3)
                for c in range(tile_c * 3, tile_c * 3 + 3)
                if grid[r][c] not in (0, 5)
            )
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out
